<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        return</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\\(numberOfWheels)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wheel(s)&quot;</span></span>
